typedef long long ll;

int cmp(const void *a, const void *b) {
    ll *x = (ll*)a, *y = (ll*)b;
    if (x[0] != y[0]) return (x[0] > y[0]) - (x[0] < y[0]);
    return (x[1] > y[1]) - (x[1] < y[1]);
}

int main() {
