    for (int i = 0; i < n; i++) scanf("%lld %lld", &a[i][0], &a[i][1]);
    qsort(a, n, sizeof(a[0]), cmp);
    // prefix min_R and suffix min_R, prefix max_L and suffix max_L
    ll prefMinR[n], sufMinR[n];
    prefMinR[0] = a[0][1]; for (int i=1;i<n;i++) prefMinR[i] = prefMinR[i-1] < a[i][1] ? prefMinR[i-1] : a[i][1];
    sufMinR[n-1] = a[n-1][1]; for (int i=n-2;i>=0;i--) sufMinR[i] = sufMinR[i+1] < a[i][1] ? sufMinR[i+1] : a[i][1];
    ll ans = 0;
    for (int k = 0; k < n-1; k++) {
        // group1 = [0..k], group2 = [k+1..n-1]
