#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll l, r;
} Interval;

static int cmpL(const void *a, const void *b) {
    const Interval *x = (const Interval *)a;
    const Interval *y = (const Interval *)b;
    if (x->l < y->l) return -1;
    if (x->l > y->l) return 1;
    if (x->r < y->r) return -1;
    if (x->r > y->r) return 1;
    return 0;
}

static int cmpR(const void *a, const void *b) {
    const Interval *x = (const Interval *)a;
    const Interval *y = (const Interval *)b;
    if (x->r < y->r) return -1;
    if (x->r > y->r) return 1;
    if (x->l < y->l) return -1;
    if (x->l > y->l) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Interval *a = (Interval *)malloc(sizeof(Interval) * N);
    Interval *byL = (Interval *)malloc(sizeof(Interval) * N);
    Interval *byR = (Interval *)malloc(sizeof(Interval) * N);

    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &a[i].l, &a[i].r);
        byL[i] = a[i];
        byR[i] = a[i];
    }

    qsort(byL, N, sizeof(Interval), cmpL);
    qsort(byR, N, sizeof(Interval), cmpR);

    ll ans = 0;

    /* Case 1:
       There exists a threshold x such that one contest gets only intervals with R < x,
       the other gets only intervals with L >= x.
       Then each contest joy is just the maximum individual interval length in that side,
       because intervals on each side are pairwise disjoint from the other side and can be
       assigned independently, maximizing by putting one best interval alone and the rest together.
    */
    ll bestLeft = 0;
    int pL = 0;
    for (int pR = 0; pR < N - 1; pR++) {
        ll x = byR[pR].r + 1;
        while (pL < N && byL[pL].l < x) {
            ll len = byL[pL].r - byL[pL].l + 1;
            if (len > bestLeft) bestLeft = len;
            pL++;
        }
        if (pL == pR + 1 && pL < N) {
            ll bestRight = 0;
            for (int i = pL; i < N; i++) {
                ll len = byL[i].r - byL[i].l + 1;
                if (len > bestRight) bestRight = len;
            }
            if (bestLeft + bestRight > ans) ans = bestLeft + bestRight;
        }
    }

    /* Case 2:
       Otherwise, optimal partition is by one interval alone vs all others.
       For each i, compute intersection of all intervals except i.
    */
    if (N >= 2) {
        ll *prefL = (ll *)malloc(sizeof(ll) * N);
        ll *prefR = (ll *)malloc(sizeof(ll) * N);
        ll *sufL = (ll *)malloc(sizeof(ll) * N);
        ll *sufR = (ll *)malloc(sizeof(ll) * N);

        prefL[0] = a[0].l;
        prefR[0] = a[0].r;
        for (int i = 1; i < N; i++) {
            prefL[i] = prefL[i - 1] > a[i].l ? prefL[i - 1] : a[i].l;
            prefR[i] = prefR[i - 1] < a[i].r ? prefR[i - 1] : a[i].r;
        }

        sufL[N - 1] = a[N - 1].l;
        sufR[N - 1] = a[N - 1].r;
        for (int i = N - 2; i >= 0; i--) {
            sufL[i] = sufL[i + 1] > a[i].l ? sufL[i + 1] : a[i].l;
            sufR[i] = sufR[i + 1] < a[i].r ? sufR[i + 1] : a[i].r;
        }

        for (int i = 0; i < N; i++) {
            ll L, R;
            if (i == 0) {
                L = sufL[1];
                R = sufR[1];
            } else if (i == N - 1) {
                L = prefL[N - 2];
                R = prefR[N - 2];
            } else {
                L = prefL[i - 1] > sufL[i + 1] ? prefL[i - 1] : sufL[i + 1];
                R = prefR[i - 1] < sufR[i + 1] ? prefR[i - 1] : sufR[i + 1];
            }

            ll joyOthers = (L <= R) ? (R - L + 1) : 0;
            ll joySingle = a[i].r - a[i].l + 1;
            if (joyOthers + joySingle > ans) ans = joyOthers + joySingle;
        }

        free(prefL);
        free(prefR);
        free(sufL);
        free(sufR);
    }

    printf("%lld\n", ans);

    free(a);
    free(byL);
    free(byR);
    return 0;
}

