int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> L(N), R(N);
    for (int i = 0; i < N; i++) {
        cin >> L[i] >> R[i];
    }

    // Precompute global prefix and suffix max L / min R
    vector<long long> pref_maxL(N), suff_maxL(N);
    vector<long long> pref_minR(N), suff_minR(N);

    pref_maxL[0] = L[0];
    pref_minR[0] = R[0];
    for (int i = 1; i < N; i++) {
        pref_maxL[i] = max(pref_maxL[i-1], L[i]);
        pref_minR[i] = min(pref_minR[i-1], R[i]);
    }

    suff_maxL[N-1] = L[N-1];
    suff_minR[N-1] = R[N-1];
    for (int i = N-2; i >= 0; i--) {
        suff_maxL[i] = max(suff_maxL[i+1], L[i]);
        suff_minR[i] = min(suff_minR[i+1], R[i]);
    }

    long long ans = 0;
    for (int i = 0; i < N; i++) {
        long long solo = R[i] - L[i] + 1;

        long long otherL = 1, otherR = 1e9;
        if (i > 0) {
            otherL = max(otherL, pref_maxL[i-1]);
            otherR = min(otherR, pref_minR[i-1]);
        }
        if (i < N-1) {
            otherL = max(otherL, suff_maxL[i+1]);
            otherR = min(otherR, suff_minR[i+1]);
        }
        long long other = max(0LL, otherR - otherL + 1);
        ans = max(ans, solo + other);
    }

    cout << ans << "\n";
    return 0;
}

