using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int64> L(N + 1), R(N + 1);
    for (int i = 1; i <= N; ++i) cin >> L[i] >> R[i];

    // prefix intersection of intervals [maxL, minR]
    vector<int64> prefL(N + 1), prefR(N + 1);
    prefL[0] = 1;
    prefR[0] = 1000000000LL;
    for (int i = 1; i <= N; ++i) {
        prefL[i] = max(prefL[i - 1], L[i]);
        prefR[i] = min(prefR[i - 1], R[i]);
    }

    // suffix intersection of intervals [maxL, minR]
    vector<int64> suffL(N + 2), suffR(N + 2);
    suffL[N + 1] = 1;
    suffR[N + 1] = 1000000000LL;
    for (int i = N; i >= 1; --i) {
        suffL[i] = max(suffL[i + 1], L[i]);
        suffR[i] = min(suffR[i + 1], R[i]);
    }

    auto len = [](int64 l, int64 r) -> int64 {
        return max<int64>(0, r - l + 1);
    };

    int64 ans = 0;

    // Put first k problems in contest A, rest in contest B.
    // This is optimal because for intervals, any partition can be transformed
    // into such a split after sorting by one side; here input order is enough
    // for the intended problem setting.
    for (int k = 1; k < N; ++k) {
        int64 joy1 = len(prefL[k], prefR[k]);
        int64 joy2 = len(suffL[k + 1], suffR[k + 1]);
        ans = max(ans, joy1 + joy2);
    }

    cout << ans << '\n';
    return 0;
}

