int main(){
    int n; cin>>n;
    vector<long long> L(n),R(n);
    for(int i=0;i<n;i++) cin>>L[i]>>R[i];
    // sort by L
    vector<int> idx(n); iota(idx.begin(),idx.end(),0);
    sort(idx.begin(),idx.end(),[&](int a,int b){return L[a]<L[b];});
    vector<long long> sL(n),sR(n);
    for(int i=0;i<n;i++){sL[i]=L[idx[i]];sR[i]=R[idx[i]];}
    // prefix minR, suffix minR, suffix maxL
    vector<long long> preMinR(n),sufMinR(n);
    preMinR[0]=sR[0]; for(int i=1;i<n;i++) preMinR[i]=min(preMinR[i-1],sR[i]);
    sufMinR[n-1]=sR[n-1]; for(int i=n-2;i>=0;i--) sufMinR[i]=min(sufMinR[i+1],sR[i]);
    long long ans=0;
    // partition: first j+1 problems in A, rest in B (j from 0 to n-2)
    // But we can also mix. Let's try: A gets a contiguous prefix, B gets rest? No that's not general.
    // Key insight: sort by L. For optimal solution, one group's problems form a prefix and other a suffix? Not necessarily.
    // Let's try all splits where A={0..j} B={j+1..n-1}
    for(int j=0;j<n-1;j++){
        long long jA=max(0LL, preMinR[j]-sL[j]+1);
        long long jB=max(0LL, sufMinR[j+1]-sL[n-1]+1);
        ans=max(ans,jA+jB);
    }
    // Also consider: for each problem i in A (with max L), best is to have only i in A
    // and rest in B. But "rest in B" maxL = sL[n-1].
    for(int i=0;i<n;i++){
        // A = {i}, B = all others
        long long jA=max(0LL,sR[i]-sL[i]+1);
        // B: maxL = sL[n-1] if i!=n-1, else sL[n-2]
        // minR of B = min of all R except i
        // This is O(n^2), need prefix/suffix
        long long minRB;
        if(i==0) minRB=sufMinR[1];
        else if(i==n-1) minRB=preMinR[n-2];
        else minRB=min(preMinR[i-1],sufMinR[i+1]);
        long long maxLB=(i==n-1)?sL[n-2]:sL[n-1];
        long long jB=max(0LL,minRB-maxLB+1);
        ans=max(ans,jA+jB);
    }
    cout<<ans<<endl;
}

