public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[][] problems = new int[n][2];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            problems[i][0] = Integer.parseInt(st.nextToken());
            problems[i][1] = Integer.parseInt(st.nextToken());
        }
        Arrays.sort(problems, (a, b) -> a[0] - b[0]);
        // prefix min R: prefR[i] = min R[0..i]
        int[] prefR = new int[n];
        prefR[0] = problems[0][1];
        for (int i = 1; i < n; i++) prefR[i] = Math.min(prefR[i-1], problems[i][1]);
        // suffix min R: sufR[i] = min R[i..n-1]
        int[] sufR = new int[n];
        sufR[n-1] = problems[n-1][1];
        for (int i = n-2; i >= 0; i--) sufR[i] = Math.min(sufR[i+1], problems[i][1]);

        long ans = 0;
        // k = index of max-L problem in group A, group B has problem n-1 as max-L
        for (int k = 0; k < n-1; k++) {
            long fA = Math.max(0L, (long)problems[k][1] - problems[k][0] + 1);
            // group B: problems k+1..n-1 and 0..k-1
            int minRB = sufR[k+1];
            if (k > 0) minRB = Math.min(minRB, prefR[k-1]);
            long fB = Math.max(0L, (long)minRB - problems[n-1][0] + 1);
            ans = Math.max(ans, fA + fB);
        }
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Interval {
        long l, r;
        Interval(long l, long r) {
            this.l = l;
            this.r = r;
        }
    }

    static long intersectionLength(long maxL, long minR) {
        return Math.max(0L, minR - maxL + 1);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        Interval[] a = new Interval[N];
        for (int i = 0; i < N; i++) {
            long l = fs.nextLong();
            long r = fs.nextLong();
            a[i] = new Interval(l, r);
        }

        // Prefix intersection of [0..i]
        long[] prefL = new long[N];
        long[] prefR = new long[N];
        prefL[0] = a[0].l;
        prefR[0] = a[0].r;
        for (int i = 1; i < N; i++) {
            prefL[i] = Math.max(prefL[i - 1], a[i].l);
            prefR[i] = Math.min(prefR[i - 1], a[i].r);
        }

        // Suffix intersection of [i..N-1]
        long[] suffL = new long[N];
        long[] suffR = new long[N];
        suffL[N - 1] = a[N - 1].l;
        suffR[N - 1] = a[N - 1].r;
        for (int i = N - 2; i >= 0; i--) {
            suffL[i] = Math.max(suffL[i + 1], a[i].l);
            suffR[i] = Math.min(suffR[i + 1], a[i].r);
        }

        long answer = 0;

        // If we split problems into two non-empty groups, and one group is a subset S,
        // then its joyfulness is intersection(S), and the other is intersection(complement).
        // For maximizing sum, it is enough to consider S as a prefix/suffix after sorting by L
        // and also after sorting by R. We evaluate all such cuts.

        // Sort by L
        Arrays.sort(a, Comparator.comparingLong(o -> o.l));
        prefL[0] = a[0].l;
        prefR[0] = a[0].r;
        for (int i = 1; i < N; i++) {
            prefL[i] = Math.max(prefL[i - 1], a[i].l);
            prefR[i] = Math.min(prefR[i - 1], a[i].r);
        }
        suffL[N - 1] = a[N - 1].l;
        suffR[N - 1] = a[N - 1].r;
        for (int i = N - 2; i >= 0; i--) {
            suffL[i] = Math.max(suffL[i + 1], a[i].l);
            suffR[i] = Math.min(suffR[i + 1], a[i].r);
        }
        for (int i = 0; i < N - 1; i++) {
            long left = intersectionLength(prefL[i], prefR[i]);
            long right = intersectionLength(suffL[i + 1], suffR[i + 1]);
            answer = Math.max(answer, left + right);
        }

        // Sort by R
        Arrays.sort(a, Comparator.comparingLong(o -> o.r));
        prefL[0] = a[0].l;
        prefR[0] = a[0].r;
        for (int i = 1; i < N; i++) {
            prefL[i] = Math.max(prefL[i - 1], a[i].l);
            prefR[i] = Math.min(prefR[i - 1], a[i].r);
        }
        suffL[N - 1] = a[N - 1].l;
        suffR[N - 1] = a[N - 1].r;
        for (int i = N - 2; i >= 0; i--) {
            suffL[i] = Math.max(suffL[i + 1], a[i].l);
            suffR[i] = Math.min(suffR[i + 1], a[i].r);
        }
        for (int i = 0; i < N - 1; i++) {
            long left = intersectionLength(prefL[i], prefR[i]);
            long right = intersectionLength(suffL[i + 1], suffR[i + 1]);
            answer = Math.max(answer, left + right);
        }

        System.out.println(answer);
    }
}
